              "{\"articleSection\":[\"politics\"],\"author\":[{\"name\":\"Daniel Shane\"}],\"dateModified\":\"2019-01-04T20:47:23Z\",\"headline\":\"China, US set for upcoming talks in Beijing\",\"alternativeHeadline\":\"China, US set for upcoming talks in Beijing\",\"inLanguage\":\"en\",\"publisher\":{\"name\":\"CNN\",\"foundingDate\":\"1980-06-01\",\"sameAs\":[\"https://www.facebook.com/cnn/\",\"https://x.com/CNN\",\"https://www.tiktok.com/@cnn\",\"https://www.instagram.com/cnn/\",\"https://www.youtube.com/cnn\"]},\"timeRequired\":\"P0Y0M0DT0H2M36S\",\"wordCount\":588,\"video\":[{\"dateModified\":\"2019-01-03T22:33:58Z\",\"uploadDate\":\"2019-01-03T22:33:58Z\",\"duration\":\"PT00H01M26S\",\"caption\":[{\"encodingFormat\":\"vtt\",\"inLanguage\":\"en\"},{\"encodingFormat\":\"srt\",\"inLanguage\":\"en\"}],\"inLanguage\":\"en\",\"name\":\"Dow plunges over Apple's dive, China trade war fears\",\"headline\":\"Dow plunges over Apple's dive, China trade war fears\",\"description\":\"The stock market took a nose dive Thursday after Apple failed to meet expectations and renewed fears about a China trade war. CNN's Alison Kosik reports.\"}],\"datePublished\":\"2019-01-04T09:56:17Z\",\"isAccessibleForFree\":false,\"hasPart\":{\"isAccessibleForFree\":false}}"
            ]
          },
